# bacteria_1111010.py
import os
import sys
import base64
import random
import re

# ================== 遗传信息 ==================
# 这里原本是一串 base64 编码的图片。
germ_plasm = ""

# ================== 还原方法 ==================
# 说明：
#   - 每个已繁殖过的内部节点，其 germ_plasm 已被替换为等长的全零字节序列，
#     对异或结果没有贡献。
#   - 只有从未繁殖过的叶子节点参与异或。
#   - 所有叶子节点的 germ_plasm 解码后异或起来，恰好等于最初根节点的原始 germ_plasm 的解码。

# ================== 繁殖逻辑 ==================
def reproduce():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    current_file = os.path.basename(__file__)
    if current_file.endswith('.py'):
        current_name = current_file[:-3]
    else:
        current_name = current_file

    prefix = 'bacteria_'
    if current_name.startswith(prefix):
        suffix = current_name[len(prefix):]
    else:
        suffix = ''

    child0_name = f"{prefix}{suffix}0"
    child1_name = f"{prefix}{suffix}1"
    child0_file = f"{child0_name}.py"
    child1_file = f"{child1_name}.py"
    child0_path = os.path.join(script_dir, child0_file)
    child1_path = os.path.join(script_dir, child1_file)

    # 如果两个子代都已存在，则不再繁殖
    if os.path.exists(child0_path) and os.path.exists(child1_path):
        return

    # 打乱 germ_plasm：先解码出真实字节，再做异或掩码
    original_bytes = base64.b64decode(germ_plasm)
    mask = bytes(random.getrandbits(8) for _ in range(len(original_bytes)))
    child0_bytes = bytes(a ^ b for a, b in zip(original_bytes, mask))
    child1_bytes = mask
    child0_germ = base64.b64encode(child0_bytes).decode('ascii')
    child1_germ = base64.b64encode(child1_bytes).decode('ascii')

    # 生成两个子代文件（此时父文件还是原始 germ_plasm）
    create_bacteria_file(child0_path, child0_germ)
    create_bacteria_file(child1_path, child1_germ)

    # 修改自身，添加对子代的导入和调用，并把自身 germ_plasm 清零
    modify_self(child0_name, child1_name, len(original_bytes))


def create_bacteria_file(filepath, germ):
    """基于当前文件生成一个干净的细菌文件，替换 germ_plasm 和文件名注释。"""
    with open(os.path.abspath(__file__), 'r', encoding='utf-8') as f:
        content = f.read()

    # 移除已有的子代导入
    content = re.sub(r'^from bacteria_\w+ import cheer as cheer\d+\n', '', content, flags=re.MULTILINE)
    # 移除 active() 中的 cheer 调用
    content = content.replace('    cheer0()\n', '')
    content = content.replace('    cheer1()\n', '')

    # 替换 germ_plasm
    content = re.sub(r'^germ_plasm = ".*"$', f'germ_plasm = "{germ}"', content, flags=re.MULTILINE)
    # 替换第一行注释为新的文件名
    content = re.sub(r'^# .*$', f'# {os.path.basename(filepath)}', content, count=1, flags=re.MULTILINE)

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)


def modify_self(child0_name, child1_name, germ_length):
    """在自身文件中添加子代导入，并在 active() 的 CHEER_CALLS 标记处插入调用。
    同时将自身 germ_plasm 清零（等长的全零字节序列），使其不再直接泄露原始遗传信息。"""
    filepath = os.path.abspath(__file__)
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    import0 = f"from {child0_name} import cheer as cheer0\n"
    import1 = f"from {child1_name} import cheer as cheer1\n"
    content = ''.join(lines)

    # 插入导入语句（如果尚未存在）
    if import0 not in content:
        for i, line in enumerate(lines):
            if line.startswith('germ_plasm ='):
                lines.insert(i + 1, import0)
                lines.insert(i + 2, import1)
                break

    # 只匹配 active() 中带缩进的 # CHEER_CALLS
    for i, line in enumerate(lines):
        if line.strip() == '# CHEER_CALLS' and line.startswith('    '):
            lines.insert(i + 1, "    cheer0()\n")
            lines.insert(i + 2, "    cheer1()\n")
            break

    with open(filepath, 'w', encoding='utf-8') as f:
        f.writelines(lines)

    # 清零自身 germ_plasm
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    zero_germ = base64.b64encode(b"\x00" * germ_length).decode('ascii')
    content = re.sub(r'^germ_plasm = ".*"$', f'germ_plasm = "{zero_germ}"', content, flags=re.MULTILINE)
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)


# ================== 主逻辑 ==================
def cheer():
    active()


def active():
    reproduce()
    print("Long Live the Great King!")
    # CHEER_CALLS


if __name__ == '__main__':
    # 确保脚本所在目录在 sys.path 中，以便导入子代模块
    script_dir = os.path.dirname(os.path.abspath(__file__))
    if script_dir not in sys.path:
        sys.path.insert(0, script_dir)
    active()